UPDATE lessons SET title='Year 3, Week 19, Lesson 2: Counting and comparing amounts of money', data=json_patch(data,'{"child_mission":"Counting and comparing money means finding each total in dollars and cents, then deciding which amount is greater using place value of dollars then cents.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same method to a larger number or a new context, then compare two solution paths for accuracy.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nCompare and order: $3.50; $3.05; $4.00. Total two $1 and seven 10c.\n\nFEEDBACK\nOrder: $3.05; $3.50; $4.00. Total $1+$1+$0.70=$2.70.\n\nWATCH FOR\nComparing only the cent digits (80>05) while ignoring dollars gives the wrong order.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nMake ten money amounts (list coins/notes). Find each total, then order five of them from least to greatest with a comparison reason for each neighbouring pair.\n\nWrite a short reflection naming one step you corrected and why.","interactive_activities":null,"learning_area":"Mathematics","learning_intention":"Counting and comparing money means finding each total in dollars and cents, then deciding which amount is greater using place value of dollars then cents.","lesson_number":2,"lesson_role":"Strategies","materials":["Paper or typed answer space","Pencil","Optional: place-value chart or number line"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["MA2-RN-01"],"parent_notes":"Parent: Marking guidance for the independent task: Make ten money amounts (list coins/notes). Find each total, then order five of them from least to greatest with a comparison reason for each ne